import { toAccessMap } from "../../src/domain/shopAccess";
import type {
  ShopAccessCatalog,
  ShopAccessEntry,
} from "../../src/types";

import payload from "../../data/shop-access.json";

// SAFETY: generated by `scripts/refresh-access.ts`, which validates the payload
// with `ShopAccessCatalogSchema` before writing it.
const DATA = payload as unknown as ShopAccessCatalog;

const ACCESS = toAccessMap(DATA.entries);

/**
 * The whole access table, for callers that join it themselves (the gp-earning
 * leaderboard needs it for three different row families at once).
 */
export const ACCESS_MAP: ReadonlyMap<string, ShopAccessEntry> = ACCESS;

/**
 * The known access requirement for a shop, or undefined when the wiki-backed
 * table does not list one. Undefined means unknown, not "accessible".
 */
export function accessFor(shopPage: string): ShopAccessEntry | undefined {
  return ACCESS.get(shopPage);
}
